window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-620c53e8935546a5"]={"versions": [{"id": "FIG-620c53e8935546a5", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Bit-Layout-Diagramm (Serialisierungs- und Header-Format) im Kontext des SOME/IP-Transformators (Communication Management, AUTOSAR Classic &amp; Adaptive Platform). Es spezifiziert die On-the-Wire-Struktur von SOME/IP Struct Tags zur typ- und feldbasierten Serialisierung strukturierter Datentypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High-Byte, Bits 7 bis 0):</strong>\n<ul class=\"fig-list\"><li><code>reserved</code>: Bit 7 (1 Bit).\n</li><li><code>Wire Type</code>: Bits 6 bis 4 (3 Bit, Bestimmung des Typs bzw. der Repräsentation nachfolgender Daten).\n</li><li><code>Data ID (Higher Sig. Part)</code>: Bits 3 bis 0 (4 Bit, höherwertiger Teil der Feldkennung).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low-Byte, Bits 7 bis 0):</strong>\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: Bits 7 bis 0 (8 Bit, niederwertiger Teil der Feldkennung).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionale Metadaten und Payload):</strong>\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Längenfeld mit Bitbreiten 8, 16 oder 32 Bit (nummeriert 7/15/31 bis 0), durch eckige Klammern als konditional/abhängig vom Wire Type gekennzeichnet.\n</li><li><code>Member Data ...</code>: Nutzdaten des Strukturelements fester oder variabler Länge.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Serialisierungssequenz dar:</p>\n<ol class=\"fig-list\"><li>Das Tag wird als 2-Byte-Präfix übertragen (Byte n gefolgt von Byte n+1 in Netzwerk-Byte-Reihenfolge).\n</li><li>Auswertung von Bit 7 (<code>reserved</code>), Bits 6–4 (<code>Wire Type</code>) und den zusammengesetzten Bits 3–0 aus Byte n sowie Bits 7–0 aus Byte n+1 zur Bestimmung der 12-Bit <code>Data ID</code>.\n</li><li>Abhängig vom serialisierten <code>Wire Type</code> folgt unmittelbar das Längenfeld (<code>Length Field</code> mit 8, 16 oder 32 Bit) oder direkt das Nutzdatenfeld.\n</li><li>Abschließend folgen die Elementdaten (<code>Member Data ...</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Bit- und Feldanordnung für Tag-basierte SOME/IP-Serialisierung (Data ID gesamt 12 Bit: 4 Bit High, 8 Bit Low).\n</li><li>Bit-Nummerierung: Bit 7 ist MSB, Bit 0 ist LSB eines jeden Bytes.\n</li><li>Das Längenfeld ist nur bei bestimmten komplexen oder dynamischen Wire Types vorhanden. Implementierungen des SOME/IP-Transformers müssen die Auswertung des Längenfeldes strikt an den decodierten Wire Type koppeln.\n</li><li>Das reservierte Bit (Bit 7 in Byte n) ist für zukünftige Protokollerweiterungen vorgesehen und spezifikationskonform zu behandeln.\n</li></ul>"}, {"id": "FIG-6d219f4418e0639a", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Bit-Layout-Diagramm (Serialisierungs- und Header-Format) im Kontext des SOME/IP-Transformators (Communication Management, AUTOSAR Classic &amp; Adaptive Platform). Es spezifiziert die On-the-Wire-Struktur von SOME/IP Struct Tags zur typ- und feldbasierten Serialisierung strukturierter Datentypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High-Byte, Bits 7 bis 0):</strong>\n<ul class=\"fig-list\"><li><code>reserved</code>: Bit 7 (1 Bit).\n</li><li><code>Wire Type</code>: Bits 6 bis 4 (3 Bit, Bestimmung des Typs bzw. der Repräsentation nachfolgender Daten).\n</li><li><code>Data ID (Higher Sig. Part)</code>: Bits 3 bis 0 (4 Bit, höherwertiger Teil der Feldkennung).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low-Byte, Bits 7 bis 0):</strong>\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: Bits 7 bis 0 (8 Bit, niederwertiger Teil der Feldkennung).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionale Metadaten und Payload):</strong>\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Längenfeld mit Bitbreiten 8, 16 oder 32 Bit (nummeriert 7/15/31 bis 0), durch eckige Klammern als konditional/abhängig vom Wire Type gekennzeichnet.\n</li><li><code>Member Data ...</code>: Nutzdaten des Strukturelements fester oder variabler Länge.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Serialisierungssequenz dar:</p>\n<ol class=\"fig-list\"><li>Das Tag wird als 2-Byte-Präfix übertragen (Byte n gefolgt von Byte n+1 in Netzwerk-Byte-Reihenfolge).\n</li><li>Auswertung von Bit 7 (<code>reserved</code>), Bits 6–4 (<code>Wire Type</code>) und den zusammengesetzten Bits 3–0 aus Byte n sowie Bits 7–0 aus Byte n+1 zur Bestimmung der 12-Bit <code>Data ID</code>.\n</li><li>Abhängig vom serialisierten <code>Wire Type</code> folgt unmittelbar das Längenfeld (<code>Length Field</code> mit 8, 16 oder 32 Bit) oder direkt das Nutzdatenfeld.\n</li><li>Abschließend folgen die Elementdaten (<code>Member Data ...</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Bit- und Feldanordnung für Tag-basierte SOME/IP-Serialisierung (Data ID gesamt 12 Bit: 4 Bit High, 8 Bit Low).\n</li><li>Bit-Nummerierung: Bit 7 ist MSB, Bit 0 ist LSB eines jeden Bytes.\n</li><li>Das Längenfeld ist nur bei bestimmten komplexen oder dynamischen Wire Types vorhanden. Implementierungen des SOME/IP-Transformers müssen die Auswertung des Längenfeldes strikt an den decodierten Wire Type koppeln.\n</li><li>Das reservierte Bit (Bit 7 in Byte n) ist für zukünftige Protokollerweiterungen vorgesehen und spezifikationskonform zu behandeln.\n</li></ul>"}], "trans": [{"from": "FIG-620c53e8935546a5", "to": "FIG-6d219f4418e0639a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6d219f4418e0639a", "to": "FIG-620c53e8935546a5", "fr": "R19-03", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
